"""docich#4894: a crowded castle's status panel pages at four names.

「しょうぐんNめい」 is the resident total, not the page size: with five or
more stationed generals the panel's name column still shows four names, so
demanding ``len(names) == count`` made castle_verify refuse every repair.
A truncated page still proves the castle and can prove presence; absence is
settled on the sortie list, the complete manifest (the carry manifest's
route, v519).
"""
from pathlib import Path
import sys
sys.path.insert(0, str(Path(__file__).resolve().parents[2] / "src"))

from docich.hanjuku_speedrun import hanjuku_house as house
from docich.hanjuku_speedrun import hanjuku_policy as p
from docich.hanjuku_speedrun.hanjuku.state.regions import world as _world
from docich.hanjuku_speedrun.hanjuku_font import TextLine
from docich.hanjuku_speedrun.hanjuku_screen import Screen


PAGE = ['ゼウス', 'ココット', 'クミン', 'ガルバンゾー']


def castle_status(castle, shown, total):
    """The status panel: ``total`` residents but only ``shown`` names on its page."""
    lines = [TextLine(95 + 16 * i, tuple((144 + 8 * j, ch) for j, ch in enumerate(n)))
             for i, n in enumerate(shown)]
    text = f'{castle}じょうステータスしゅうにゅう しょうぐん{total}めい' + ''.join(shown)
    return Screen(lines=lines, hand=None, text=text, kind='text')


def generals(names, cursor=0):
    """The sortie list's visible page; ``cursor`` is the row the hand sits on."""
    lines = [TextLine(39 + 16 * i, tuple((144 + 8 * j, c) for j, c in enumerate(n)))
             for i, n in enumerate(names)]
    hand = (122, 33 + 16 * cursor, 139, 45 + 16 * cursor)
    return Screen(lines=lines, hand=hand, text=''.join(names), kind='general_list')


def memory(**fields):
    mem = {'chapter': 1, 'month': '1-7', 'gold': 250, 'tick': 500,
           'captured': ['カストーラ'], 'castle_ownership': {},
           'house': {'phase': 'castle_verify', 'chapter': 1, 'age': 0, 'total': 0,
                     'general': 'ゼウス', 'source': 'カストーラ',
                     'castles': ['カストーラ'],
                     'pending': [], 'seen': [], 'inspected': []}}
    mem['house'].update(fields)
    return mem


def test_five_residents_four_visible_names_is_not_a_read_failure():
    mem = memory()
    actions = house._repair_step(castle_status('カストーラ', PAGE, 5), mem, None)
    assert actions == [p.pad('b')]
    assert mem['house']['phase'] == 'castle_sortie'
    # A truncated page must not be persisted as the whole garrison (v678/#3963).
    assert 'カストーラ' not in (_world(mem).get('garrison') or {})


def test_target_on_a_later_page_still_opens_the_sortie_list():
    mem = memory(general='ソーピニヨン')
    actions = house._repair_step(castle_status('カストーラ', PAGE, 5), mem, None)
    assert actions == [p.pad('b')]
    assert mem['house']['phase'] == 'castle_sortie'
    assert any(r['decision'] == 'house_castle_verify_partial' for r in mem['_records'])


def test_small_castle_incomplete_read_still_refuses():
    mem = memory(general='ソーピニヨン')
    house._repair_step(castle_status('カストーラ', PAGE[:2], 3), mem, None)
    assert mem['house']['phase'] == 'close'


def test_complete_small_panel_unchanged():
    mem = memory()
    house._repair_step(castle_status('カストーラ', ['ゼウス', 'ココット'], 2), mem, None)
    assert mem['house']['phase'] == 'castle_sortie'
    assert (_world(mem).get('garrison') or {})['カストーラ'] == ['ゼウス', 'ココット']


def test_absent_on_a_complete_small_panel_moves_to_the_next_castle():
    mem = memory(general='ソーピニヨン')
    house._repair_step(castle_status('カストーラ', ['ゼウス', 'ココット'], 2), mem, None)
    assert mem['house']['phase'] == 'find_castle'


def test_pick_scans_a_full_page_for_an_off_page_target():
    mem = memory(phase='castle_pick', general='ソーピニヨン', pick_scan=None)
    # First page lacks the target: walk the list instead of giving up.
    assert house._repair_step(generals(PAGE), mem, None) == [p.pad('down')]
    assert mem['house']['phase'] == 'castle_pick'
    # Scrolled page brings the target into view; it is selected normally.
    assert house._repair_step(generals(PAGE[1:] + ['ソーピニヨン'], cursor=3), mem, None) == [p.pad('a')]
    assert mem['house']['phase'] == 'castle_kit'


def test_pick_wrap_ends_the_search_and_moves_to_the_next_castle():
    mem = memory(phase='castle_pick', general='ソーピニヨン', pick_scan=None)
    assert house._repair_step(generals(PAGE), mem, None) == [p.pad('down')]
    # Five residents in a four-row page: the last row scrolls into view.
    assert house._repair_step(generals(PAGE[1:] + ['ラズベリー'], cursor=3), mem, None) == [p.pad('down')]
    # The cursor coming back to the first row proves the whole list was walked.
    assert house._repair_step(generals(PAGE), mem, None) == [p.pad('b')]
    assert mem['house']['phase'] == 'find_castle'


def test_a_short_complete_list_moves_to_the_next_castle_immediately():
    mem = memory(phase='castle_pick', general='ソーピニヨン', pick_scan=None)
    assert house._repair_step(generals(['ゼウス']), mem, None) == [p.pad('b')]
    assert mem['house']['phase'] == 'find_castle'


def test_a_general_found_on_a_later_page_is_not_a_sole_defender():
    mem = memory(phase='castle_pick', general='ソーピニヨン', pick_scan=None)
    house._repair_step(generals(PAGE), mem, None)
    # The last resident page can show the target alone: one visible row is a
    # page remainder, not a one-man garrison, once earlier pages were walked.
    actions = house._repair_step(generals(['ソーピニヨン']), mem, None)
    assert actions == [p.pad('a')]
    assert not mem['house'].get('sole_defender')
